{
  "assessments": [
    {
      "proposition_id": "P1",
      "status": "full",
      "summary_quote": "Under the first change, a parent of a participating student would have to make sure the student takes, each year, all Tennessee comprehensive assessment program (TCAP) tests, or successor tests authorized by the state board of education. These are the tests given to public school students in the same grade or course subject.",
      "rationale": "Conveys the parent's duty, annual testing, authorized successors, and grade-or-course matching. The summary identifies the amended subsection and separately states its disability exemption."
    },
    {
      "proposition_id": "P2",
      "status": "full",
      "summary_quote": "A parent of a student in grade eleven would also have to make sure the student takes the exam given to public school eleventh graders under § 49-6-6001(b)(1).",
      "rationale": "States the parent's duty, grade, and required examination. The disability exemption is stated later in the same paragraph."
    },
    {
      "proposition_id": "P3",
      "status": "partial",
      "summary_quote": "A parent of a student in kindergarten through grade three would have to make sure the student takes each of the three Tennessee universal reading screeners, or screeners approved by the state board of education. The student would take each one during each of the three administration windows set by the department of education.",
      "rationale": "Conveys the parent obligation, grades, screeners, approved alternatives, and administration windows, with the exemption stated separately. It does not specify that reading screening must occur annually; the earlier annual language applies expressly to TCAP tests."
    },
    {
      "proposition_id": "P4",
      "status": "full",
      "summary_quote": "Test results would have to be reported to the parent.",
      "rationale": "In context, this states the reporting requirement for tests under the first replacement subsection."
    },
    {
      "proposition_id": "P5",
      "status": "full",
      "summary_quote": "Students with disabilities who would have taken alternate assessments, as set by their IEP, would be exempt from these requirements.",
      "rationale": "Conveys the disability exemption, its alternate-assessment eligibility condition, the IEP determination, and its application to the subsection's requirements."
    },
    {
      "proposition_id": "P6",
      "status": "full",
      "summary_quote": "Under the second change, the same testing rules would become conditions of participating in the program: annual TCAP or successor tests, the grade eleven exam, and the three reading screeners in kindergarten through grade three.",
      "rationale": "States annual TCAP or successor testing as a participation condition. 'The same testing rules' incorporates the preceding state-board authorization and grade-or-course matching requirements, and the amendment target is identified earlier."
    },
    {
      "proposition_id": "P7",
      "status": "full",
      "summary_quote": "Under the second change, the same testing rules would become conditions of participating in the program: annual TCAP or successor tests, the grade eleven exam, and the three reading screeners in kindergarten through grade three.",
      "rationale": "Makes the grade-eleven examination a participation condition and incorporates the examination identified in the preceding paragraph."
    },
    {
      "proposition_id": "P8",
      "status": "partial",
      "summary_quote": "Under the second change, the same testing rules would become conditions of participating in the program: annual TCAP or successor tests, the grade eleven exam, and the three reading screeners in kindergarten through grade three.",
      "rationale": "Conveys the K–3 screening participation condition and incorporates the previously described screeners, approved alternatives, and windows. Neither description states that reading screening is required annually."
    },
    {
      "proposition_id": "P9",
      "status": "full",
      "summary_quote": "The act would take effect July 1, 2025.",
      "rationale": "States the exact effective date."
    }
  ]
}
